import os, csv, json, numpy as np

N = 26
TOL = 1e-8
EXP_DIR = 'storage/noesis/exports/exp284'
SOTA243_DIR = 'storage/noesis/exports/sota_243'
NMAP_DIR = 'storage/noesis/nmap'

def ensure_dir(p):
    os.makedirs(p, exist_ok=True)

def load_latest():
    c = np.loadtxt('storage/noesis/latest_centers.txt')
    r = np.loadtxt('storage/noesis/latest_radii.txt')
    c = np.array(c, dtype=float).reshape(N, 2)
    r = np.array(r, dtype=float).reshape(N,)
    return c, r

def boundary_actives(centers, radii, tol=TOL):
    x = centers[:,0]; y = centers[:,1]; r = radii
    acts = []
    for i in range(N):
        if x[i] - r[i] <= tol: acts.append((i, 'xL'))
        if 1.0 - x[i] - r[i] <= tol: acts.append((i, 'xR'))
        if y[i] - r[i] <= tol: acts.append((i, 'yB'))
        if 1.0 - y[i] - r[i] <= tol: acts.append((i, 'yT'))
    return acts

def pair_actives(centers, radii, tol=TOL):
    acts = []
    for i in range(N):
        for j in range(i+1, N):
            d = np.hypot(centers[i,0]-centers[j,0], centers[i,1]-centers[j,1])
            if d - (radii[i] + radii[j]) <= tol:
                acts.append((i, j))
    return acts

def write_csv(path, rows, header=None):
    ensure_dir(os.path.dirname(path))
    with open(path, 'w', newline='') as f:
        w = csv.writer(f)
        if header: w.writerow(header)
        for r in rows: w.writerow(r)

def write_txt_matrix(path, arr):
    ensure_dir(os.path.dirname(path))
    with open(path, 'w') as f:
        if arr.ndim == 2:
            for i in range(arr.shape[0]):
                f.write(f"{arr[i,0]:.9f} {arr[i,1]:.9f}\n")
        else:
            for i in range(arr.shape[0]):
                f.write(f"{arr[i]:.9f}\n")

def load_pairs_csv(path):
    S = set()
    with open(path, 'r') as f:
        for line in f:
            toks = [t for t in line.replace(',', ' ').split() if t]
            if len(toks) < 2: continue
            try:
                i = int(float(toks[0])); j = int(float(toks[1]))
            except Exception:
                continue
            a, b = (i, j) if i <= j else (j, i)
            S.add((a, b))
    return S

def load_boundary_csv(path):
    S = set()
    canon = {'xl':'xL','left':'xL','l':'xL','x_left':'xL',
             'xr':'xR','right':'xR','r':'xR','x_right':'xR',
             'yb':'yB','bottom':'yB','b':'yB','y_bottom':'yB',
             'yt':'yT','top':'yT','t':'yT','y_top':'yT',
             'xL':'xL','xR':'xR','yB':'yB','yT':'yT'}
    with open(path, 'r') as f:
        for line in f:
            toks = [t for t in line.replace(',', ' ').split() if t]
            if len(toks) < 2: continue
            try:
                i = int(float(toks[0]))
            except Exception:
                continue
            s = canon.get(toks[1].strip(), toks[1].strip())
            S.add((i, s))
    return S

def jaccard(A, B):
    I = A & B; U = A | B
    J = float(len(I))/float(len(U)) if len(U) > 0 else 1.0
    return J, I, U

def construct_packing():
    centers, radii = load_latest()
    ensure_dir(EXP_DIR)

    # Export exp284 active sets and snapshot
    b_acts = boundary_actives(centers, radii, tol=TOL)
    p_acts = pair_actives(centers, radii, tol=TOL)
    write_csv(f"{EXP_DIR}/active_boundary_tol1e8.csv", b_acts, header=['i','side'])
    write_csv(f"{EXP_DIR}/active_pairs_tol1e8.csv", p_acts, header=['i','j'])
    write_txt_matrix(f"{EXP_DIR}/centers.txt", centers)
    write_txt_matrix(f"{EXP_DIR}/radii.txt", radii)
    summary = {"n": N, "sum_r": float(np.sum(radii)),
               "boundary_count": len(b_acts), "pairs_count": len(p_acts)}
    with open(f"{EXP_DIR}/summary_tol1e8.json", 'w') as f:
        json.dump(summary, f, indent=2, sort_keys=True)

    # Compute Jaccard vs SOTA 243 (using published exports)
    try:
        A_pairs = load_pairs_csv(f"{EXP_DIR}/active_pairs_tol1e8.csv")
        B_pairs = load_pairs_csv(f"{SOTA243_DIR}/active_pairs_tol1e8.csv")
        A_bound = load_boundary_csv(f"{EXP_DIR}/active_boundary_tol1e8.csv")
        B_bound = load_boundary_csv(f"{SOTA243_DIR}/active_boundary_tol1e8.csv")
        Jb, Ib, Ub = jaccard(A_bound, B_bound)
        Jp, Ip, Up = jaccard(A_pairs, B_pairs)
        out_prefix = f"{NMAP_DIR}/jaccard_exp284_vs_sota243_tol1e8"
        os.makedirs(NMAP_DIR, exist_ok=True)
        with open(out_prefix + ".json", 'w') as f:
            json.dump({
                "n": N,
                "boundary": {"jaccard": Jb, "intersection_size": len(Ib), "union_size": len(Ub)},
                "pairs":    {"jaccard": Jp, "intersection_size": len(Ip), "union_size": len(Up),
                             "symdiff_size": len(Up)-len(Ip)}
            }, f, indent=2, sort_keys=True)
        with open(out_prefix + ".csv", 'w', newline='') as f:
            w = csv.writer(f)
            w.writerow(['n','boundary_j','boundary_intersection','boundary_union',
                        'pairs_j','pairs_intersection','pairs_union','pairs_symdiff'])
            w.writerow([N, Jb, len(Ib), len(Ub), Jp, len(Ip), len(Up), len(Up)-len(Ip)])
    except Exception:
        pass

    # Return the same packing unchanged
    return centers, radii
